parameters.query:
SELECT ut.*
FROM user_topics ut
JOIN topics t ON ut.topic_id = t.id
WHERE ut.user_id = (
  SELECT id FROM users WHERE telegram_id = {{ $json.user_id }}
)
AND t.name = LOWER('{{ $json.topic_name }}');

