SELECT u.telegram_id, STRING_AGG(t.name, ', ') AS subscribed_topics
FROM users u
JOIN user_topics ut ON u.id = ut.user_id
JOIN topics t ON ut.topic_id = t.id
WHERE u.telegram_id = {{ $json.result.chat.id }}
GROUP BY u.telegram_id;

