const input = $('Code2').first().json.payload;

// Xoá prefix command
const content = input.replace('/update_content', '').trim();

// Tách theo dấu "/"
const parts = content.split('/');

if (parts.length < 3) {
  throw new Error('Error. Sai định dạng. Vui lòng dùng /updatecontent {id}/{chủ đề}/{nội dung mới}');
}

return [{
  json: {
    topic_data_id: parseInt(parts[0].trim()),
    topic_name: parts[1].trim(),
    new_content: parts.slice(2).join('/').trim(), // để hỗ trợ dấu "/" trong nội dung
    telegram_id: $('Handle any trigger in telegram').first().json.message.chat.id
  }
}];

const input = $input.first().json.message.text;

const parts = input.split(' ');

const payload = parts.slice(1).join(' ').trim();

return [{
  json: {
    full_command: parts[0], // "/insert_content"
    payload: payload         // "Thể thao/ronaldo là cầu thủ số 1 thế giới"
  }
}];

const input = $input.first().json.payload;
const parts = input.split('/');

if (parts.length < 2) {
  throw new Error('Error. Sai định dạng. Vui lòng dùng /insertcontent {chủ đề}/{nội dung}');
}

return [{
  json: {
    topic_name: parts[0].trim(),
    content: parts.slice(1).join('/').trim(), // để hỗ trợ dấu '/' trong nội dung
    telegram_id: $('Handle any trigger in telegram').first().json.message.chat.id
  }
}];

parameters.query:
UPDATE topic_data
SET content = '{{$json.new_content}}',
    created_at = NOW()
WHERE topic_id = {{$json.topic_data_id}}
  AND user_id = (
    SELECT id FROM users WHERE telegram_id = {{$json.telegram_id}}
  );

SELECT id, topic_id, content
FROM topic_data
WHERE id = (SELECT MAX(id) FROM topic_data);

